%[text] # Illustration: Two Ways to Make a Legend
%[text] MATLAB offers two ways to label lines in a legend: 
%[text] 1. List in `legend` call afterwards, or 
%[text] 2. Label when plotted  with `'DisplayName'`. \
%[text] Both draw the same legend.
x = linspace(0, 2, 50);
%%
%[text] ## Method 1: List in `legend` call 
figure(); %[output:3258c92e]
hold on %[output:3258c92e]
plot(x, x) %[output:3258c92e]
plot(x, x.^2) %[output:3258c92e]
plot(x, x.^3) %[output:3258c92e]
legend('x', 'x^2', 'x^3') %[output:3258c92e]
hold off %[output:3258c92e]
%[text] The curves (plots) and their labels are disconnected. 
%%
%[text] ### Common error - change the plotting, but forget to update the legend list. 
%[text] Add a plot line at the start, and keep the same `legend` call:
figure(); %[output:3bf462e3]
hold on %[output:3bf462e3]
plot([0 2], [1 1], 'k--') %[output:3bf462e3]
plot(x, x) %[output:3bf462e3]
plot(x, x.^2) %[output:3bf462e3]
plot(x, x.^3) %[output:3bf462e3]
legend('x', 'x^2', 'x^3') %[output:3bf462e3]
hold off %[output:3bf462e3]
%[text] No syntax error, but a sematic one!
%%
%[text] ## Method 2: Label when plotted  with `'DisplayName'`.
figure(); %[output:9fd478b2]
hold on %[output:9fd478b2]
plot([0 2], [1 1], 'k--', 'DisplayName', 'Reference') %[output:9fd478b2]
plot(x, x, 'DisplayName', 'x') %[output:9fd478b2]
plot(x, x.^2, 'DisplayName', 'x^2') %[output:9fd478b2]
plot(x, x.^3, 'DisplayName', 'x^3') %[output:9fd478b2]
legend() %[output:9fd478b2]
hold off %[output:9fd478b2]
%[text] Each label belongs to its own line, so the legend stays correct when lines are added or reordered.

